const listConversationsForUser = `-- name: ListConversationsForUser :many
SELECT
    c.id,
    c.tenant_id,
    c.type,
    c.project_id,
    c.title,
    c.created_by_user_id,
    c.last_message_seq,
    c.last_message_at,
    c.created_at,
    c.updated_at,

    COALESCE(cm.role, '')::text AS member_role,
    COALESCE(cm.last_read_seq, 0)::bigint AS last_read_seq,

    COALESCE((
        SELECT COUNT(*)
        FROM messages m
        WHERE
            m.conversation_id = c.id
            AND m.seq > COALESCE(cm.last_read_seq, 0)
            AND m.deleted_at IS NULL
            AND (
                m.author_user_id IS NULL
                OR m.author_user_id <> $1::text
            )
    ), 0)::bigint AS unread_count,

    COALESCE(lm.kind, '')::text AS last_message_kind,
    COALESCE(lm.body, '')::text AS last_message_body,
    lm.author_user_id AS last_message_author_user_id,
    lm.created_at AS last_message_created_at
FROM conversations c
LEFT JOIN conversation_members cm ON
    cm.conversation_id = c.id
    AND cm.tenant_id = c.tenant_id
    AND cm.user_id = $1::text
LEFT JOIN LATERAL (
    SELECT
        m.kind,
        m.body,
        m.author_user_id,
        m.created_at
    FROM messages m
    WHERE m.conversation_id = c.id
    ORDER BY m.seq DESC
    LIMIT 1
) lm ON TRUE
WHERE
    c.tenant_id = $2::text
    AND (
        cm.user_id IS NOT NULL
        OR (c.type = 'project' AND $3::bool)
    )
ORDER BY
    c.last_message_at DESC NULLS LAST,
    c.created_at DESC
LIMIT $4
`

